/**
 * Unified asset registry for the 8-stage asset library.
 *
 * The registry is driven by the manifests generated by
 * `tools/assets/build-asset-manifest.mjs` (public/assets/manifest.json +
 * per-level manifests). It is additive infrastructure: the verified Stage-1
 * loader (`src/gfx/pack.ts`) is untouched, and this module does not rewire any
 * game system. It exists so future stages can declare, resolve and load their
 * assets through one auditable path with explicit failure reporting.
 *
 * Rules enforced here:
 *  - one stable Asset ID per asset (shared assets are referenced, never duplicated)
 *  - missing assets raise AssetNotFoundError — never a silent placeholder swap
 *  - publish mode only loads assets whose license permits distribution
 *  - images are cached; `dispose()` releases everything (no cross-level leaks)
 *  - load progress is reported through an optional callback
 */

export type LicenseStatus =
  | 'LICENSE_VERIFIED'
  | 'LICENSE_PARTIAL'
  | 'LICENSE_UNKNOWN'
  | 'THIRD_PARTY_RESTRICTED'
  | 'PERMISSION_REQUIRED'
  | 'APPROVED_FOR_PROJECT';

export type CoverageStatus =
  | 'AVAILABLE_AND_VERIFIED'
  | 'AVAILABLE_NOT_VERIFIED'
  | 'PARTIAL'
  | 'MISSING'
  | 'LICENSE_BLOCKED';

export interface AssetEntry {
  /** path relative to the manifest that declares it */
  file: string;
  kind: string;
  title?: string;
  license: LicenseStatus;
  licenseBasis?: string;
  status: string;
  publishable: boolean;
  bytes?: number;
  sha256?: string;
  width?: number;
  height?: number;
  format?: string;
  hasAlpha?: boolean;
  sourceSheet?: Record<string, unknown>;
}

export interface SharedRef {
  manifest: string;
  id: string;
}

export interface LevelManifest {
  schemaVersion: number;
  level: string;
  title: string;
  coverage: CoverageStatus;
  notes?: string;
  assets: Record<string, AssetEntry>;
  sharedRefs: Record<string, SharedRef>;
  gaps: string[];
}

export interface TopManifest {
  schemaVersion: number;
  licensePolicy: {
    publishRequires: LicenseStatus[];
    note?: string;
  };
  shared: Record<string, AssetEntry>;
  levelIndex: Record<string, { title: string; coverage: CoverageStatus; manifest: string }>;
}

export class AssetNotFoundError extends Error {
  readonly assetId: string;
  readonly levelId?: string;
  constructor(assetId: string, levelId?: string) {
    super(
      levelId
        ? `asset "${assetId}" not found for level "${levelId}"`
        : `shared asset "${assetId}" not found`,
    );
    this.name = 'AssetNotFoundError';
    this.assetId = assetId;
    this.levelId = levelId;
  }
}

export class AssetLicenseError extends Error {
  constructor(assetId: string, license: LicenseStatus) {
    super(`asset "${assetId}" (license ${license}) is not approved for publish builds`);
    this.name = 'AssetLicenseError';
  }
}

export interface AssetLoaderHooks {
  fetchJson(url: string): Promise<unknown>;
  loadImage(url: string): Promise<unknown>;
}

export interface RegistryOptions {
  /** refuse to load assets that are not approved for distribution */
  publishMode?: boolean;
  onProgress?: (loaded: number, total: number, assetId: string) => void;
}

interface CacheItem {
  url: string;
  image: unknown;
}

export class AssetRegistry {
  private readonly hooks: AssetLoaderHooks;
  private readonly opts: RegistryOptions;
  private top: TopManifest | null = null;
  private topUrl = '';
  private readonly levels = new Map<string, { manifest: LevelManifest; url: string }>();
  private readonly cache = new Map<string, CacheItem>();
  private readonly inflight = new Map<string, Promise<unknown>>();

  constructor(hooks: AssetLoaderHooks, opts: RegistryOptions = {}) {
    this.hooks = hooks;
    this.opts = opts;
  }

  /** Load the top-level manifest. `baseUrl` is the manifest URL itself. */
  async load(baseUrl = 'assets/manifest.json'): Promise<TopManifest> {
    this.topUrl = baseUrl;
    this.top = (await this.hooks.fetchJson(baseUrl)) as TopManifest;
    return this.top;
  }

  private requireTop(): TopManifest {
    if (!this.top) throw new Error('AssetRegistry.load() must be called first');
    return this.top;
  }

  /** Load a level manifest (cached per level). */
  async loadLevel(levelId: string): Promise<LevelManifest> {
    const cached = this.levels.get(levelId);
    if (cached) return cached.manifest;
    const top = this.requireTop();
    const idx = top.levelIndex[levelId];
    if (!idx) throw new AssetNotFoundError(`level:${levelId}`);
    const url = resolveUrl(idx.manifest, this.topUrl);
    const manifest = (await this.hooks.fetchJson(url)) as LevelManifest;
    this.levels.set(levelId, { manifest, url });
    return manifest;
  }

  /** Resolve a shared asset entry by ID (throws when unknown). */
  getShared(id: string): AssetEntry {
    const entry = this.requireTop().shared[id];
    if (!entry) throw new AssetNotFoundError(id);
    return entry;
  }

  /**
   * Resolve any asset (level-local or shared-referenced) to its entry plus the
   * absolute URL the file can be fetched from.
   */
  resolve(levelId: string, assetId: string): { entry: AssetEntry; url: string } {
    const level = this.levels.get(levelId);
    if (!level) throw new AssetNotFoundError(assetId, levelId);
    const local = level.manifest.assets[assetId];
    if (local) return { entry: local, url: resolveUrl(local.file, level.url) };
    const ref = level.manifest.sharedRefs[assetId];
    if (ref) {
      const entry = this.getShared(ref.id);
      return { entry, url: resolveUrl(entry.file, this.topUrl) };
    }
    throw new AssetNotFoundError(assetId, levelId);
  }

  /** Load (and cache) an image. Missing or non-publishable assets fail loudly. */
  async getImage(assetId: string, levelId?: string): Promise<unknown> {
    const { entry, url } = levelId ? this.resolve(levelId, assetId) : { entry: this.getShared(assetId), url: resolveUrl(this.getShared(assetId).file, this.topUrl) };
    if (this.opts.publishMode && !entry.publishable) throw new AssetLicenseError(assetId, entry.license);
    const cached = this.cache.get(url);
    if (cached) return cached.image;
    const pending = this.inflight.get(url);
    if (pending) return pending;
    const promise = this.hooks.loadImage(url).then((image) => {
      this.cache.set(url, { url, image });
      this.inflight.delete(url);
      this.opts.onProgress?.(this.cache.size, this.cache.size, assetId);
      return image;
    }).catch((err) => {
      this.inflight.delete(url);
      throw err instanceof Error && err.message.includes(url)
        ? err
        : new Error(`failed to load asset "${assetId}" from ${url}: ${String(err)}`);
    });
    this.inflight.set(url, promise);
    return promise;
  }

  /** Assets referenced by a level whose file cannot be produced (gap list). */
  listLevelGaps(levelId: string): string[] {
    const level = this.levels.get(levelId);
    return level ? [...level.manifest.gaps] : [];
  }

  get loadedCount(): number {
    return this.cache.size;
  }

  /** Release every cached image (call on level teardown to avoid leaks). */
  dispose(): void {
    this.cache.clear();
    this.inflight.clear();
    this.levels.clear();
    this.top = null;
    this.topUrl = '';
  }
}

/** Resolve a manifest-relative path against the manifest's own URL. */
export function resolveUrl(relPath: string, manifestUrl: string): string {
  if (/^(https?:)?\/\//.test(relPath) || relPath.startsWith('/')) return relPath;
  const m = /^(https?:\/\/[^/]+)?(\/.*)?$/.exec(manifestUrl);
  const origin = m?.[1] ?? '';
  const basePath = (m?.[2] ?? manifestUrl).replace(/[^/]*$/, '');
  const joined = origin + basePath + relPath;
  const parts: string[] = [];
  for (const seg of joined.slice(origin.length).split('/')) {
    if (seg === '' || seg === '.') continue;
    if (seg === '..') parts.pop();
    else parts.push(seg);
  }
  return origin ? `${origin}/${parts.join('/')}` : parts.join('/');
}

/** Browser-default hooks (fetch + Image). */
export function browserHooks(): AssetLoaderHooks {
  return {
    fetchJson: async (url) => {
      const res = await fetch(url);
      if (!res.ok) throw new Error(`manifest fetch failed: ${res.status} ${url}`);
      return res.json();
    },
    loadImage: (url) => new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error(`image load failed: ${url}`));
      img.src = url;
    }),
  };
}
